INSERT INTO publications (id,submission_id,version,title,abstract,keywords,references_text,issue_id,section_id,pages,doi,copyright_holder,copyright_year,license_url,status,date_published,seq) VALUES
(6386,6386,1,'Digital Exposure of Minor Children and the Exercise of Parental Responsibility in the Peruvian Legal System','<p>This article analyzed how the digital exposure of minor children relates to the exercise of parental responsibility within the Peruvian legal system during 2025-2026. A basic study was conducted using a qualitative approach and a legal hermeneutic design. Ten legal professionals—eight lawyers, one judge, and one prosecutor—were interviewed, and ten legal documents were examined using an interview guide and a document analysis guide. The results showed that the dissemination of photographs, videos, and personal data must be evaluated based on the child''s rights to privacy, image, identity, and security. Parental representation does not represent an unrestricted right; the duty to protect encompasses the risks arising from the permanence and reproduction of content that forms a digital footprint, and progressive autonomy requires considering the child''s age, maturity, and wishes regarding the monetization of their image. The study concluded that parental rights must be exercised as a caregiving function, attending to the best interests of the child and the specific circumstances of each publication.</p>','["Children''s rights, privacy, parental responsibility, digital identity"]',NULL,37,1,'2029 - 2043',NULL,'The Authors',2026,'https://creativecommons.org/licenses/by/4.0/','published','2026-09-15',1),
(6387,6387,1,'Rüppell Fox Optimizer for Economic and Emissions Dispatch of Microgrid Involving Renewables','<p>The combined economic and emissions dispatch (CEED) of microgrids (MGs) is considered a complex optimization problem. Its goal is to balance between the costs of power generation while minimizing emissions. By integrating renewable energy sources such as solar and wind, the MG may lower its relying on high-emission conventional generators. The aim is to find the most effective power level for each resource that minimizes both the fuel consumption and the total emission output of MG. To obtain a reliable supply of energy, the dispatch process must meet physical and operational constraints. Furthermore, the total power produced by combined renewable and traditional sources must be equal to or greater than the total loads. Additionally, each generator operates within certain boundaries that reduce the equipment overstress. The utilization of the Rüppell Fox Optimizer (RFO) offers superior performance in balancing the intermittent nature of RESs with conventional generation in the MG. By simulating advanced foraging behaviors, RFO identifies the optimum operating points that minimize both total operation costs and emissions while satisfying MG different constraints. Comparative results verify that RFO achieves lowest total costs than standard meta-heuristic methods, proving its robustness for sustainable and cost-effective MG management.</p>','["Combined economic and emissions dispatch, microgrids, R\\u00fcppell fox optimizer, renewable energy"]',NULL,37,1,'2044 - 2062',NULL,'The Authors',2026,'https://creativecommons.org/licenses/by/4.0/','published','2026-09-15',2),
(6388,6388,1,'Non-Contractual Civil Liability for Deficiencies in Maternal-Neonatal Care in Peru','<p>This article analyzes extra-contractual civil liability arising from deficiencies in maternal and neonatal care in Peru, considering state obligations and the legal difficulties in determining damages caused during healthcare provision. Its objective was to analyze the configuration of this liability within public maternal and neonatal health programs during 2024-2025. Basic, qualitative research was conducted using legal interpretation and case analysis. Semi-structured interviews were conducted with eight lawyers, one physician, and one obstetrician, supplemented by a review of ten court cases using document analysis forms. The results identified difficulties in proving healthcare non-compliance, establishing causal links, and differentiating professional conduct from organizational deficiencies, particularly in cases of diagnostic delays, therapeutic omissions, and limitations in healthcare resources. The interviews and court rulings revealed differences in the assessment of medical records, expert reports, and the criteria used to quantify compensation. It was concluded that civil liability required proof of unlawful conduct, harm, causation, and the basis for attribution, without considering the existence of obstetric or neonatal complications sufficient. Due to the qualitative scope of the study, the findings were limited to the sources analyzed, although they offer legal criteria for evaluating future disputes related to compensation for healthcare damages.</p>','["Civil liability, maternal and child health, right to health, civil law, health policy"]',NULL,37,1,'2063 - 2076',NULL,'The Authors',2026,'https://creativecommons.org/licenses/by/4.0/','published','2026-09-15',3),
